import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksForGen,validGen,advanceGen,numericGen,gridValid}from './gen-models.js?v=20261023-physicscomplete01';import{showGen}from './gen-visuals.js?v=20261023-physicscomplete01';export{showGen};
export function mountGen(l,p,root,{save,done,feedback}){let ts=tasksForGen(l.widget.slice(4)),w=p.widget;w.genTask??=ts[0].id;w.genDrafts??={};w.genPassed??=[];let i=ts.findIndex(t=>t.id===w.genTask);if(i<0)i=0;let t=ts[i],v=w.genDrafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountGen(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.genPassed.includes(t.id));
syncProcessMovie(l,1,['nucleotide','backbone','triplet','pairing','function','edit','expression','alleles','cross','limits'].includes(t.kind)?{process:false}:null);
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('genCase','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('genAnswer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealGen">Reveal evidence →</button><p id="genReadout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showGen(t.kind,{state:c[0],neutral:t.kind==='glands',title:t.title,label:c[1],concealed:!r&&t.kind!=='glands',progress:r?1:0,step:r?5:0});$('#genReadout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validGen(c,v.answer);}
else if(t.type==='sequence'){body=field('genNext','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advanceGen">Advance pathway →</button><p id="genReadout" aria-live="polite"></p>';draw=()=>{showGen(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#genReadout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}
else if(t.type==='grid'){v.cells??=['','','',''];body='<p>Row and column gametes are supplied. Complete each possible genotype.</p><div style="display:grid;grid-template-columns:40px 1fr 1fr;gap:8px;align-items:center"><span>↓ / →</span>'+t.cols.map(c=>'<strong>'+c+'</strong>').join('')+t.rows.map((r,j)=>'<strong>'+r+'</strong>'+t.cols.map((c,k)=>'<div>'+field('genCell'+(j*2+k),'Row '+(j+1)+', column '+(k+1),[['AA','AA'],['Aa','Aa'],['aa','aa']],v.cells[j*2+k])+'</div>').join('')).join('')+'</div>';draw=()=>showGen('cross',{rows:t.rows,cols:t.cols,cells:v.cells,title:t.title});valid=()=>gridValid(v,t);}
else{body='<p>'+t.prompt+'</p><label class="field-label" for="genNumber">Your result / '+(t.unit||'supplied units')+'</label><input class="lab-input" id="genNumber" type="number" step="any" value="'+(v.number??'')+'">'+field('genReason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);if(t.kind==='graph')body+='<label class="field-label" for="genDay">Inspect day</label><input id="genDay" type="range" min="1" max="28" value="'+(v.day??14)+'">';draw=()=>showGen(t.kind,{title:t.title,day:Number(v.day??14),label:'Original illustrative evidence'});valid=()=>numericGen(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="genEvidence"></p><div class="lab-actions"><button class="secondary" id="recordGen">Record reasoning</button><button class="secondary" id="nextGen">Next challenge →</button></div><p id="genProgress"></p>';
const status=()=>{$('#genEvidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):w.genPassed.includes(t.id)?'Challenge recorded.':'';$('#genProgress').textContent=ts.filter(t=>w.genPassed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='genDay'){v.day=val;save();draw();return;}if(id==='genCase'){if(val==='')return;v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(['genShoot','genRoot','genSeed','genBend'].includes(id)){v[id.slice(6).toLowerCase()]=val;draw();}else if(id.startsWith('genCell')){v.cells[Number(id.slice(7))]=val;draw();}else if(id==='genAnswer')v.answer=val;else if(id==='genNext')v.next=val;else if(id==='genNumber')v.number=val;else if(id==='genReason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{if(e.target.id==='genDay'){v.day=e.target.value;draw();}else v.number=e.target.value;save();};}
if($('#revealGen'))$('#revealGen').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validGen(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validGen(t.cases[v.case],v.answer));};
if($('#advanceGen'))$('#advanceGen').onclick=()=>{let n=advanceGen(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordGen').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);let finished=t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.genPassed.includes(t.id))w.genPassed.push(t.id);p.widgetDone=ts.every(t=>w.genPassed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':'Recorded. Compare the remaining scenarios.');};$('#nextGen').onclick=()=>{if(!w.genPassed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.genTask=ts[(i+1)%ts.length].id;save();remount();};}
